const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const fr = i => { const s = Math.sin((i*12.9898 + P.seed*78.233)) * 43758.5453; return s - Math.floor(s); };
const W=width,H=height,t=K.t,en=P.energy,sty=P.style,dc=drawingContext,TAU=Math.PI*2;
function pieceHue(i){ if(sty==='gold') return 40+fr(i)*15; if(sty==='pastel') return (i*61)%360; if(sty==='mono') return P.hue; if(sty==='rainbow') return (i*47)%360; return [0,45,140,200,280,320][i%6]; }
const psat=sty==='pastel'?45: sty==='mono'?12: 85;
const N=Math.floor(30+P.density*160);
// streamers first (behind)
if(P.streamers>0.05){ for(let i=0;i<P.streamers*20;i++){ const fall=(0.06+fr(i)*0.1)*(0.5+en)*P.speed; const yy=((fr(i)+t*fall)%1)*(H+60)-30; const xx=fr(i+7)*W + Math.sin(t*0.6+i)*30; const h=pieceHue(i);
  noFill(); stroke(color(h,psat,90, 55*P.alpha/100)); strokeWeight(3+fr(i)*3);
  beginShape(); for(let k=0;k<10;k++){ vertex(xx+Math.sin(t*2+k*0.8+i)*12, yy+k*14); } endShape(); } }
noStroke();
for(let i=0;i<N;i++){
  const fall=(0.08+fr(i)*0.18)*(0.5+en)*P.speed;
  const yy=((fr(i+3)+t*fall)%1)*(H+40)-20;
  const xx=(fr(i)*W + Math.sin(t*0.7+i)*20*P.wind + t*P.wind*30)%W;
  const sz=(4+fr(i+9)*9)*(0.5+P.size)*P.scale;
  const rot=t*(1+fr(i)*4)*P.spin*(fr(i+2)>0.5?1:-1) + i;
